def largest_prime_factor(n):
    # Start with the largest possible factor
    factor = n - 1

    # Keep dividing by factors until we find a prime factor
    while factor > 1:
        if n % factor == 0:
            # Check if the factor is prime
            is_prime = True
            for i in range(2, factor):
                if factor % i == 0:
                    is_prime = False
                    break
            if is_prime:
                return factor
        factor -= 1

