def int_to_mini_roman(num):
    roman_numerals = {
        1000: 'm', 900: 'cm', 500: 'd', 400: 'cd', 100: 'c',
        90: 'xc', 50: 'l', 40: 'xl', 10: 'x', 9: 'ix',
        5: 'v', 4: 'iv', 1: 'i'
    }
    roman_numeral = ''
    for value, numeral in roman_numerals.items():
        while num >= value:
            roman_numeral += numeral
            num -= value
    return roman_numeral

