def binomial_Coeff(n, k):
    if k > n:
        return 0
    elif k == 0 or k == n:
        return 1
    else:
        return binomial_Coeff(n-1, k-1) + binomial_Coeff(n-1, k)

def max_Prime_Factors(n):
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
    return n

