def comb_sort(arr):
    gap = len(arr)
    shrink_factor = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink_factor)
        if gap > 1:
            sorted = False
        else:
            gap = 1
            sorted = True

        i = 0
        while i + gap < len(arr):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False
            i += 1

def magic_square_test(square):
    # Check if the square is a 3x3 matrix
    if len(square) != 3 or any(len(row) != 3 for row in square):
        return False

def magic_square_test(square):
    n = len(square)
    magic_sum = n * (n ** 2 + 1) // 2

    for row in square:
        if sum(row) != magic_sum:
            return False

    for col in range(n):
        if sum(square[row][col] for row in range(n)) != magic_sum:
            return False

    if sum(square[i][i] for i in range(n)) != magic_sum or sum(square[i][n - i - 1] for i in range(n)) != magic_sum:
        return False

    return True

def reverse_vowels(s):
    vowels = "aeiouAEIOU"
    s = list(s)
    i, j = 0, len(s) - 1
    while i < j:
        while i < j and s[i] not in vowels:
            i += 1
        while i < j and s[j] not in vowels:
            j -= 1
        s[i], s[j] = s[j], s[i]
        i += 1
        j -= 1
    return "".join(s)

def month_season(month, day):
    if (month == 'January' and 1 <= day <= 31) or (month == 'February' and 1 <= day <= 28) or (month == 'March' and 1 <= day <= 31):
        return 'winter'
    elif (month == 'April' and 1 <= day <= 30) or (month == 'May' and 1 <= day <= 31) or (month == 'June' and 1 <= day <= 30):
        return 'spring'
    elif (month == 'July' and 1 <= day <= 31) or (month == 'August' and 1 <= day <= 31) or (month == 'September' and 1 <= day <= 30):
        return 'summer'
    else:
        return 'autumn'

def is_num_keith(n):
    if n < 10:
        return False

    digits = [int(d) for d in str(n)]
    seq = digits[:]
    while True:
        next_digit = sum(seq[-len(digits):])
        if next_digit in seq:
            return True
        if next_digit > n:
            return False
        seq.append(next_digit)

def is_num_keith(num):
    digits = [int(d) for d in str(num)]
    length = len(digits)
    if length < 2:
        return False
    sequence = digits.copy()
    while sequence[-1] < num:
        next_digit = sum(sequence[-length:])
        sequence.append(next_digit)
    return sequence[-1] == num

def common_prefix(strs, n):
    prefix = strs[0]
    for i in range(1, n):
        while strs[i].find(prefix) != 0:
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

def max_sum(triangle, n):
    # Initialize a DP array to store the maximum sum at each position
    dp = [[0] * n for _ in range(n)]

    # Base case: the maximum sum at the top of the triangle is the value of the top element
    dp[0][0] = triangle[0][0]

    # Fill in the DP array
    for i in range(1, n):
        for j in range(i+1):
            # The maximum sum at position (i, j) is the value of the current element plus
            # the maximum of the sums from the two elements directly above it
            dp[i][j] = triangle[i][j] + max(dp[i-1][j], dp[i-1][j-1] if j > 0 else 0)

    # The maximum sum in the triangle is the maximum value in the last row of the DP array
    return max(dp[n-1])

def max_sum(arr, n):
    inc = [0] * n
    dec = [0] * n
    inc[0] = arr[0]
    dec[n-1] = arr[n-1]

    for i in range(1, n):
        inc[i] = max(inc[i-1] + arr[i], arr[i])

    for i in range(n-2, -1, -1):
        dec[i] = max(dec[i+1] + arr[i], arr[i])

    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum

def max_sum(arr, n):
    # Initialize two arrays to store the maximum sum of increasing and decreasing subsequences
    inc = [0] * n
    dec = [0] * n

    # Initialize the maximum sum to 0
    max_sum = 0

    # Fill the inc array
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Fill the dec array
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Calculate the maximum sum of bi-tonic subsequence
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum

def lps(string):
    n = len(string)
    dp = [[0 for _ in range(n)] for _ in range(n)]

    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if string[i] == string[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

