def find_minimum_range(arrays):
    merged = []
    for arr in arrays:
        merged.extend(arr)
    merged.sort()
    min_range = float('inf')
    start = 0
    end = 0
    while end < len(merged):
        if len(set(merged[start:end+1])) >= len(arrays):
            min_range = min(min_range, merged[end]-merged[start])
            start += 1
        else:
            end += 1
    return (merged[start], merged[start] + min_range)

def find_minimum_range(arrays):
    min_heap = []
    current_max = float('-inf')
    for i, array in enumerate(arrays):
        heapq.heappush(min_heap, (array[0], i, 0))
        current_max = max(current_max, array[0])

    min_range = float('inf')
    while len(min_heap) == len(arrays):
        _, i, j = heapq.heappop(min_heap)
        if current_max - arrays[i][j] < min_range:
            min_range = current_max - arrays[i][j]
        j += 1
        if j < len(arrays[i]):
            heapq.heappush(min_heap, (arrays[i][j], i, j))
            current_max = max(current_max, arrays[i][j])
        else:
            break

    return (current_max - min_range, current_max)
